import heapq


def _quota_intervals(data, capacity, tie):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for group in combinations(jobs, k):
        ids = {job["id"] for job in group}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in group:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(name, 0) <= high
               for name, (low, high) in quotas.items()):
            continue

        active = []
        valid = True
        for job in sorted(group, key=lambda row: (row["start"], row["end"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            heapq.heappush(active, job["end"])
            if len(active) > capacity:
                valid = False
                break
        if not valid:
            continue

        selected = sorted(ids)
        value = sum(job["value"] for job in group)
        if (best_value is None or value > best_value or
                (value == best_value and
                 (selected < best_ids if tie == "smallest" else selected > best_ids))):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _build_component_01():
    return lambda data: _quota_intervals(data, 2, "smallest")


