def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        best_vector = None
        best_versions = None

        def has_cycle(chosen):
            state = {}

            def visit(name):
                mark = state.get(name, 0)
                if mark == 1:
                    return True
                if mark == 2:
                    return False
                state[name] = 1
                row = chosen[name]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    if visit(dep["name"]):
                        return True
                state[name] = 2
                return False

            return any(visit(name) for name in chosen if state.get(name, 0) == 0)

        def search(chosen, constraints):
            nonlocal best_vector, best_versions
            # Any newly accumulated bound must also hold for an assigned package.
            for name, ranges in constraints.items():
                if name in chosen and any(not low <= chosen[name]["version"] <= high
                                          for low, high in ranges):
                    return

            pending = [name for name in constraints if name not in chosen]
            if not pending:
                if has_cycle(chosen):
                    return
                versions = {name: row["version"] for name, row in chosen.items()}
                vector = tuple(versions.get(name, -1) for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector, best_versions = vector, versions
                return

            name = min(pending)
            ranges = constraints[name]
            rows = []
            for row in packages.get(name, []):
                version = row["version"]
                if any(not low <= version <= high for low, high in ranges):
                    continue
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                rows.append(row)

            # Explore higher choices first; final comparison enforces the global vector order.
            for row in sorted(rows, key=lambda item: item["version"], reverse=True):
                next_chosen = dict(chosen)
                next_chosen[name] = row
                next_constraints = {key: list(value) for key, value in constraints.items()}
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    next_constraints.setdefault(dep["name"], []).append(
                        (dep["min"], dep["max"]))
                search(next_chosen, next_constraints)

        initial = {name: [tuple(bounds)] for name, bounds in roots.items()}
        search({}, initial)
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit_for.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                    remaining - 1))
                for duration, next_remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit_for.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
        return {"arrival": None}
    return solve


